INSERT INTO `app_settings` (`key`, `value`, `updatedAt`) VALUES ('his_articles_v1','[{\"id\":\"sample-cybersecurity-his-ops\",\"title\":\"Cybersecurity in HIS: Practical Defenses for EMR Operations\",\"summary\":\"Baseline security practices for HIS teams to protect EMR systems, user accounts, and county infrastructure.\",\"bodyMarkdown\":\"## Why This Matters\\nEMR uptime and patient data integrity depend on strong daily security practices.\\n\\n## Priority Controls\\n1. Enforce strong passwords and role-based access per user\\n2. Use least-privilege access for modules and locations\\n3. Keep operating systems, browsers, and endpoint protection updated\\n4. Review asset inventories and unknown devices weekly\\n\\n## HIS Team Checklist\\n- Disable inactive user accounts immediately\\n- Escalate suspicious login activity and unexpected API failures\\n- Verify backup/restore readiness monthly\\n- Document incidents and post mitigation notes in the knowledge base\\n\\n## Outcome\\nConsistent security routines reduce service disruption risk and improve trust in EMR systems across facilities.\",\"imageUrl\":\"https://images.unsplash.com/photo-1550751827-4bd374c3f58b?auto=format&fit=crop&w=1400&q=80\",\"authorName\":\"Meshack Ariri\",\"tags\":[\"cybersecurity\",\"his\",\"emr\",\"governance\"],\"status\":\"published\",\"createdAt\":\"2026-04-07T09:00:00.000Z\",\"updatedAt\":\"2026-04-14T17:40:00.919Z\",\"publishedAt\":\"2026-04-07T09:00:00.000Z\"},{\"id\":\"5f0642bb-48f3-4898-bef3-812ad740586d\",\"title\":\"Troubleshooting EMR Servers: Clearing Cache to Resolve Common Issues\",\"summary\":\"How would you go about fixing an emr server that has backlog thanks to openmrs caching\",\"bodyMarkdown\":\"# Clearing OpenMRS Cache on a Tomcat Server\\n\\n## Overview\\n\\nIn an OpenMRS deployment, especially in production or heavily customized\\nenvironments, you may encounter issues such as:\\n\\n-   UI not updating after changes\\\\\\n-   Modules behaving inconsistently\\\\\\n-   Unexpected errors after upgrades or configuration changes\\n\\nThese problems are often caused by cached data and compiled artifacts\\nwithin the Tomcat server.\\n\\nClearing the OpenMRS cache is a safe and common troubleshooting step\\nthat forces the system to rebuild fresh runtime files.\\n\\n------------------------------------------------------------------------\\n\\n## When Should You Clear the Cache?\\n\\nYou should consider clearing the cache when:\\n\\n-   Changes to modules or configurations are not reflected\\\\\\n-   The application behaves inconsistently after deployment\\\\\\n-   You encounter unexplained UI or backend errors\\\\\\n-   After restoring a database or migrating environments\\n\\n------------------------------------------------------------------------\\n\\n## Steps to Clear OpenMRS Cache\\n\\nFollow the steps below carefully.\\n\\n### 1. Stop the Tomcat Service\\n\\nStop Tomcat to ensure no files are in use.\\n\\n``` bash\\nsudo systemctl stop tomcat9\\n```\\n\\n------------------------------------------------------------------------\\n\\n### 2. Clear Tomcat Work Directory\\n\\nThis directory contains compiled JSP files and cached data.\\n\\n``` bash\\nsudo rm -rf /var/lib/tomcat9/work/*\\n```\\n\\n------------------------------------------------------------------------\\n\\n### 3. Clear Temporary Files\\n\\nRemove temporary files that may interfere with application behavior.\\n\\n``` bash\\nsudo rm -rf /var/lib/tomcat9/temp/*\\n```\\n\\n------------------------------------------------------------------------\\n\\n### 4. Remove Deployed OpenMRS Application\\n\\nDelete the deployed OpenMRS application so it can be re-extracted\\ncleanly.\\n\\n``` bash\\nsudo rm -rf /var/lib/tomcat9/webapps/openmrs\\n```\\n\\n>  **Note:**\\\\\\n> This does NOT delete your database or application data. It only\\n> removes the deployed application files.\\n\\n------------------------------------------------------------------------\\n\\n### 5. Restart Tomcat\\n\\nStart the service again.\\n\\n``` bash\\nsudo systemctl start tomcat9\\n```\\n\\n------------------------------------------------------------------------\\n\\n### 6. Monitor the Logs\\n\\nTrack the startup process to ensure everything loads correctly.\\n\\n``` bash\\ntail -f /var/lib/tomcat9/logs/catalina.out\\n```\\n\\n------------------------------------------------------------------------\\n\\n## What Happens After Clearing Cache?\\n\\nWhen Tomcat restarts:\\n\\n-   OpenMRS will rebuild its cache\\\\\\n-   The application will be redeployed automatically\\\\\\n-   Initial startup may take longer than usual\\n\\n------------------------------------------------------------------------\\n\\n## Important Tips\\n\\n-   Always ensure you have a backup before performing server operations\\\\\\n-   Avoid interrupting Tomcat during startup after clearing cache\\\\\\n-   If issues persist, check:\\n    -   Module compatibility\\\\\\n    -   Database integrity\\\\\\n    -   Log errors in `catalina.out`\\n\\n------------------------------------------------------------------------\\n\\n## Conclusion\\n\\nClearing the OpenMRS cache is a simple yet powerful troubleshooting step\\nthat resolves many common system issues. It ensures your application\\nruns with fresh compiled resources and up-to-date configurations.\",\"imageUrl\":\"https://www.mediquant.com/wp-content/uploads/2022/09/EMR-management-system.jpeg\",\"authorName\":\"Meshack Ariri\",\"tags\":[\"emrserver\",\"cache\"],\"status\":\"published\",\"createdAt\":\"2026-04-07T07:22:21.757Z\",\"updatedAt\":\"2026-04-14T17:40:00.919Z\",\"publishedAt\":\"2026-04-07T07:22:21.757Z\"},{\"id\":\"sample-team-strides-q1\",\"title\":\"Q1 Team Strides: EMR Stability and Asset Visibility\",\"summary\":\"Highlights of what the HIS team improved in uptime, ticket turnaround, and asset tracking.\",\"bodyMarkdown\":\"## Highlights\\n- Introduced structured EMR ticket categories for quicker triage\\n- Improved assignment workflows for faster ownership\\n- Expanded visibility of server/router/simcard inventory\\n\\n## Why It Matters\\nThese changes reduce downtime and make issue resolution more predictable for facility teams.\\n\\n## Next Focus\\n1. Publish troubleshooting guides weekly\\n2. Standardize asset editing in row/column workflows\\n3. Expand progress reporting per county\",\"imageUrl\":\"https://images.unsplash.com/photo-1461749280684-dccba630e2f6?auto=format&fit=crop&w=1400&q=80\",\"authorName\":\"Meshack Ariri\",\"tags\":[\"team-strides\",\"operations\",\"progress\"],\"status\":\"published\",\"createdAt\":\"2026-04-02T10:00:00.000Z\",\"updatedAt\":\"2026-04-14T17:40:00.919Z\",\"publishedAt\":\"2026-04-02T10:00:00.000Z\"},{\"id\":\"sample-troubleshooting-network-latency\",\"title\":\"Reducing EMR Sync Delays in Rural Sites\",\"summary\":\"A practical troubleshooting sequence for frequent slow sync complaints in low-bandwidth facilities.\",\"bodyMarkdown\":\"## Context\\nSome facilities were reporting delayed EMR sync during peak hours.\\n\\n## What We Checked\\n1. Signal strength and SIM provider stability\\n2. Router uptime and restart frequency\\n3. Local LAN bottlenecks between server and client machines\\n\\n## What Worked\\n- Scheduled off-peak background sync windows\\n- Replaced unstable SIM cards in high-loss areas\\n- Updated router configuration to prioritize EMR traffic\\n\\n## Outcome\\nAverage sync delay reduced from **15-20 minutes** to **under 5 minutes** in the affected facilities.\",\"imageUrl\":\"https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=1400&q=80\",\"authorName\":\"Meshack Ariri\",\"tags\":[\"troubleshooting\",\"network\",\"emr\"],\"status\":\"published\",\"createdAt\":\"2026-04-01T08:00:00.000Z\",\"updatedAt\":\"2026-04-14T17:40:00.919Z\",\"publishedAt\":\"2026-04-01T08:00:00.000Z\"}]','2026-04-14 17:40:00.920'),('user_accounts_v1','[{\"id\":\"usr_9aecd287b93f91dc\",\"name\":\"Frank Bruno\",\"email\":\"fbruno@gmail.com\",\"passwordHash\":\"3f87361ba97456b985aff775f7578cd8:bd3fa46855e76aa063d32d2298851c081c2569d48ea3a8a7be1fb0f1e6b52365a117c142239ae55634cac668c340396f8f1c87157c17d5f9e81df8b347023724\",\"role\":\"admin\",\"locations\":[\"Nyamira\",\"Vihiga\"],\"modules\":[\"tickets\",\"assets\",\"reports\",\"dashboard\"],\"isActive\":true,\"createdAt\":\"2026-04-07T09:03:24.445Z\",\"updatedAt\":\"2026-04-07T11:43:08.265Z\"},{\"id\":\"usr_d28c4bd3f7f10fe3\",\"name\":\"Meshack Ariri\",\"email\":\"mariri@path.org\",\"passwordHash\":\"1d72b695082902b9e065af309c7f838f:e26141e7ed44ded9f91f67224828d68199d72985aa94931cf285005be3430ea2c98792d553c7d8dd325b2cb8b1c30df6bb68a649f14b02313501c54dbe283bfb\",\"role\":\"superadmin\",\"locations\":\"all\",\"modules\":[\"dashboard\",\"tickets\",\"assets\",\"facility\",\"reports\",\"uploads\",\"users\"],\"isActive\":true,\"createdAt\":\"2026-04-07T09:09:05.121Z\",\"updatedAt\":\"2026-04-07T11:40:56.026Z\"},{\"id\":\"usr_3eb4e8765488d6ce\",\"name\":\"Guest User\",\"email\":\"guest@his.org\",\"passwordHash\":\"19a61b3bdb938d357cf58e572eda21d5:fc2c32e5139ed2f5ead00e16316738866686e01987c8b0838150a20bdda88ae0e117126418627d8b5e2f98c506cdc82c4b6b10891dd9d3f63f76698680e6fa2a\",\"role\":\"guest\",\"locations\":\"all\",\"modules\":[\"tickets\"],\"isActive\":true,\"createdAt\":\"2026-04-07T13:43:19.110Z\",\"updatedAt\":\"2026-04-09T09:00:22.155Z\"},{\"id\":\"usr_eb4711f62228e562\",\"name\":\"Beryl Okuba\",\"email\":\"bokuba@path.org\",\"passwordHash\":\"3aef2b24bedf9f4dc2207e161dc57bb2:325deb9e9bf35e4523c68585fce6468fcdab89d2a0ab5c876af144730625b56898309b74234c27c69e70992b5d86be6b1f412727f100c90b5c80ff16059c2848\",\"role\":\"admin\",\"locations\":[\"Kisumu\"],\"modules\":[\"tickets\",\"dashboard\",\"assets\"],\"isActive\":true,\"createdAt\":\"2026-04-07T13:55:47.531Z\",\"updatedAt\":\"2026-04-07T13:58:31.133Z\"},{\"id\":\"usr_8ab64b91432ab8dd\",\"name\":\"LawrenceJuma\",\"email\":\"ljuma@path.org\",\"passwordHash\":\"94ef4a7a89853dab5a1c23156f1ed3f0:e83a619026a549840bb0d70