--
-- Table structure for table `tickets`
--

DROP TABLE IF EXISTS `tickets`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tickets` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `facilityName` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `serverCondition` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `problem` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `solution` text COLLATE utf8mb4_unicode_ci,
  `reportedBy` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `assignedTo` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reporterDetails` text COLLATE utf8mb4_unicode_ci,
  `resolvedBy` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `resolverDetails` text COLLATE utf8mb4_unicode_ci,
  `resolutionSteps` text COLLATE utf8mb4_unicode_ci,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open',
  `location` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `subcounty` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `serverType` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `issueType` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `week` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  `resolvedAt` datetime(3) DEFAULT NULL,
  `reporterRole` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `tickets_status_idx` (`status`),
  KEY `tickets_location_idx` (`location`),
  KEY `tickets_location_subcounty_idx` (`location`,`subcounty`),
  KEY `tickets_subcounty_idx` (`subcounty`),
  KEY `tickets_facilityName_idx` (`facilityName`),
  KEY `tickets_serverType_idx` (`serverType`),
  KEY `tickets_issueType_idx` (`issueType`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

